package cdl

import("encoding/json";"os";"path/filepath";"testing")
func TestValidateReportTargetRejectsSourceAlias(t *testing.T){d:=t.TempDir();src:=filepath.Join(d,"a.wav");if err:=os.WriteFile(src,[]byte("x"),0644);err!=nil{t.Fatal(err)};if err:=ValidateReportTarget(src,[]string{src});err==nil{t.Fatal("expected alias rejection")}}
func TestWriteReportAtomicAndJSON(t *testing.T){d:=t.TempDir();out:=filepath.Join(d,"report.json");r:=Report{Tool:"x",Version:"dev",GeneratedUTC:"2026-01-01T00:00:00Z",Inputs:[]string{"a\n.wav"},Dependencies:map[string]string{},Options:map[string]any{},Measurements:map[string]any{},Findings:[]Finding{},Status:"ok"};if err:=WriteReportAtomic(out,r);err!=nil{t.Fatal(err)};b,err:=os.ReadFile(out);if err!=nil{t.Fatal(err)};var got map[string]any;if err:=json.Unmarshal(b,&got);err!=nil{t.Fatalf("invalid json: %v\n%s",err,b)}}
func TestWriteReportAtomicReplacesExisting(t *testing.T){d:=t.TempDir();out:=filepath.Join(d,"report.json");if err:=os.WriteFile(out,[]byte("old"),0644);err!=nil{t.Fatal(err)};r:=NewReport("replacement",[]string{"a.wav"});if err:=WriteReportAtomic(out,r);err!=nil{t.Fatal(err)};b,err:=os.ReadFile(out);if err!=nil{t.Fatal(err)};var got Report;if err:=json.Unmarshal(b,&got);err!=nil{t.Fatal(err)};if got.Tool!="replacement"{t.Fatalf("%q",got.Tool)};matches,err:=filepath.Glob(filepath.Join(d,".cdl-report-*.tmp"));if err!=nil{t.Fatal(err)};if len(matches)!=0{t.Fatalf("temporary files left behind: %v",matches)}}
func TestFindAudioFilesDeterministic(t *testing.T){d:=t.TempDir();for _,n:=range []string{"z.wav","a.flac","ignore.txt"}{if err:=os.WriteFile(filepath.Join(d,n),[]byte("x"),0644);err!=nil{t.Fatal(err)}};got,err:=FindAudioFiles(d,false);if err!=nil{t.Fatal(err)};if len(got)!=2||filepath.Base(got[0])!="a.flac"||filepath.Base(got[1])!="z.wav"{t.Fatalf("unexpected order: %#v",got)}}
func TestParseArgsSupportsInputBeforeFlags(t *testing.T){p,err:=ParseArgs([]string{"in.wav","--json","--output","x.json"},map[string]bool{"--json":true},map[string]bool{"--output":true});if err!=nil{t.Fatal(err)};if len(p.Positionals)!=1||p.Positionals[0]!="in.wav"||!p.Bools["--json"]||p.Values["--output"]!="x.json"{t.Fatalf("bad parse: %#v",p)}}
